        ["admin.console.local.failed"] = Multi("Impossible de charger le diagnostic de l'assistant local.", "Could not load local-assistant diagnostics.", "No se pudo cargar el diagnóstico del asistente local.", "Não foi possível carregar o diagnóstico do assistente local.", "Diagnose des lokalen Assistenten konnte nicht geladen werden.", "Impossibile caricare la diagnostica dell'assistente locale."),
        ["admin.console.tools.title"] = Multi("Outils documentaires", "Document tools", "Herramientas documentales", "Ferramentas documentais", "Dokumentwerkzeuge", "Strumenti documentali"),
        ["admin.console.tools.subtitle"] = Multi("Accès rapide au catalogue, aux catégories, à l'arborescence et aux recherches documentaires.", "Quick access to the catalog, categories, tree view, and document searches.", "Acceso rápido al catálogo, categorías, árbol y búsquedas documentales.", "Acesso rápido ao catálogo, categorias, árvore e pesquisas documentais.", "Schneller Zugriff auf Katalog, Kategorien, Baumansicht und Dokumentsuche.", "Accesso rapido a catalogo, categorie, albero e ricerche documentali."),
        ["admin.console.tools.help"] = Multi("Ces outils ouvrent les informations dans la discussion active afin de garder une trace lisible : liste des catégories, statistiques, arborescence et recherche guidée. Ils ne relancent pas d'ingestion par eux-mêmes.", "These tools open information in the active chat so it stays readable: category list, statistics, tree view, and guided search. They do not restart ingestion by themselves.", "Estas herramientas abren la información en la conversación activa para conservar una traza legible: lista de categorías, estadísticas, árbol y búsqueda guiada. No relanzan la ingesta por sí solas.", "Estas ferramentas abrem a informação na conversa ativa para manter um registo legível: lista de categorias, estatísticas, árvore e pesquisa guiada. Não relançam a ingestão sozinhas.", "Diese Werkzeuge öffnen Informationen im aktiven Chat, damit eine lesbare Spur bleibt: Kategorienliste, Statistiken, Baumansicht und geführte Suche. Sie starten keine Ingestion selbst neu.", "Questi strumenti aprono le informazioni nella chat attiva per mantenerne una traccia leggibile: elenco categorie, statistiche, albero e ricerca guidata. Non rilanciano l'ingestione da soli."),
        ["admin.console.tools.categories.help"] = Multi("Affiche toutes les catégories disponibles sur le serveur avec leur volume documentaire. Utile pour vérifier ce qui est disponible avant de poser une question.", "Shows every category available on the server with its document volume. Useful for checking what is available before asking a question.", "Muestra todas las categorías disponibles en el servidor con su volumen documental. Útil para comprobar qué está disponible antes de preguntar.", "Mostra todas as categorias disponíveis no servidor com o respetivo volume documental. Útil para verificar o que está disponível antes de perguntar.", "Zeigt alle auf dem Server verfügbaren Kategorien mit Dokumentumfang. Nützlich, um vor einer Frage die Verfügbarkeit zu prüfen.", "Mostra tutte le categorie disponibili sul server con il relativo volume documentale. Utile per verificare cosa è disponibile prima di chiedere."),
        ["admin.console.tools.tree.help"] = Multi("Affiche l'arborescence réelle de la base documentaire. C'est le meilleur aperçu pour comprendre comment les dossiers et catégories sont organisés.", "Shows the real document-library tree. This is the best overview for understanding how folders and categories are organized.", "Muestra el árbol real de la base documental. Es la mejor vista para entender cómo se organizan carpetas y categorías.", "Mostra a árvore real da base documental. É a melhor visão para perceber como pastas e categorias estão organizadas.", "Zeigt die echte Baumstruktur der Dokumentbasis. Das ist die beste Übersicht über Ordner und Kategorien.", "Mostra l'albero reale della base documentale. È la vista migliore per capire come sono organizzate cartelle e categorie."),
        ["admin.console.tools.stats.help"] = Multi("Résume le nombre de documents, catégories et états connus. Pratique pour contrôler rapidement si l'index reflète bien le dépôt documentaire.", "Summarizes known documents, categories, and states. Useful to quickly check whether the index reflects the document repository.", "Resume documentos, categorías y estados conocidos. Práctico para comprobar rápido si el índice refleja el repositorio documental.", "Resume documentos, categorias e estados conhecidos. Útil para verificar rapidamente se o índice reflete o repositório documental.", "Fasst bekannte Dokumente, Kategorien und Zustände zusammen. Praktisch zur schnellen Kontrolle, ob der Index den Dokumentbestand abbildet.", "Riassume documenti, categorie e stati noti. Utile per verificare rapidamente se l'indice riflette l'archivio documentale."),
        ["admin.console.tools.search.help"] = Multi("Ouvre l'aide guidée pour chercher un document, filtrer par catégorie ou lancer une action admin autorisée.", "Opens guided help to search for a document, filter by category, or run an authorized admin action.", "Abre la ayuda guiada para buscar un documento, filtrar por categoría o ejecutar una acción admin autorizada.", "Abre a ajuda guiada para pesquisar um documento, filtrar por categoria ou executar uma ação admin autorizada.", "Öffnet die geführte Hilfe zum Suchen eines Dokuments, Filtern nach Kategorie oder Starten einer erlaubten Admin-Aktion.", "Apre la guida assistita per cercare un documento, filtrare per categoria o avviare un'azione admin autorizzata."),
        ["admin.console.tools.open_in_chat"] = Multi("Afficher dans le chat", "Show in chat", "Mostrar en el chat", "Mostrar no chat", "Im Chat anzeigen", "Mostra in chat"),
        ["admin.console.tools.open_help"] = Multi("Ouvrir l'aide guidée", "Open guided help", "Abrir ayuda guiada", "Abrir ajuda guiada", "Geführte Hilfe öffnen", "Apri guida assistita"),
        ["admin.console.tools.note"] = Multi("Si aucune discussion n'est ouverte, connecte d'abord le client : les résultats de ces outils sont ajoutés comme messages pour rester consultables.", "If no chat is open, connect the client first: these tool results are added as messages so they remain easy to review.", "Si no hay conversación abierta, conecta primero el cliente: los resultados se añaden como mensajes para poder revisarlos.", "Se não houver conversa aberta, liga primeiro o cliente: os resultados são adicionados como mensagens para ficarem consultáveis.", "Wenn kein Chat geöffnet ist, verbinde zuerst den Client: die Ergebnisse werden als Nachrichten abgelegt und bleiben nachvollziehbar.", "Se non c'è una chat aperta, collega prima il client: i risultati vengono aggiunti come messaggi per restare consultabili."),
        ["help.direct.empty_response"] = Multi("L'outil n'a renvoyé aucun résultat exploitable.", "The tool did not return a usable result.", "La herramienta no devolvió ningún resultado utilizable.", "A ferramenta não devolveu um resultado utilizável.", "Das Werkzeug hat kein nutzbares Ergebnis geliefert.", "Lo strumento non ha restituito un risultato utilizzabile."),
        ["help.direct.error_short"] = Multi("l'action n'a pas pu être terminée. Le détail technique est conservé dans les logs.", "the action could not be completed. Technical details were kept in the logs.", "la acción no pudo completarse. El detalle técnico queda en los logs.", "a ação não pôde ser concluída. O detalhe técnico ficou nos logs.", "die Aktion konnte nicht abgeschlossen werden. Technische Details stehen in den Logs.", "l'azione non è stata completata. I dettagli tecnici sono nei log."),
